package server.bots;
import client.Character;import org.junit.jupiter.api.Test;import scripting.event.EventInstanceManager;import server.expeditions.PinkBeanLives;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BotPinkBeanLivesTest {
 private Character exhausted(){var b=mock(Character.class);var e=mock(EventInstanceManager.class);when(b.getEventInstance()).thenReturn(e);when(b.getId()).thenReturn(7);when(e.getName()).thenReturn("PinkBean2");when(e.getProperty("pinkDeathLimit")).thenReturn("5");when(e.getProperty("pinkDeaths:7")).thenReturn("5");return b;}
 @Test void fifthDeathWaitsUntilClearButOtherEventsAndFourDeathsDoNot(){var b=exhausted();assertTrue(PinkBeanLives.exhausted(b));assertTrue(BotPinkBeanRecovery.waitForResurrection(b,java.util.List.of()));when(b.getEventInstance().isEventCleared()).thenReturn(true);assertFalse(PinkBeanLives.exhausted(b));when(b.getEventInstance().isEventCleared()).thenReturn(false);when(b.getEventInstance().getProperty("pinkDeaths:7")).thenReturn("4");assertFalse(PinkBeanLives.exhausted(b));when(b.getEventInstance().getName()).thenReturn("HorntailBattle2");assertFalse(PinkBeanLives.exhausted(b));}
 @Test void nativeResurrectionCannotRestoreAnExhaustedParticipant()throws Exception{var b=exhausted();var effect=new server.StatEffect();var id=server.StatEffect.class.getDeclaredField("sourceid");id.setAccessible(true);id.setInt(effect,constants.skills.Bishop.RESURRECTION);var apply=server.StatEffect.class.getDeclaredMethod("applyTo",Character.class,Character.class,boolean.class,java.awt.Point.class,boolean.class,int.class);apply.setAccessible(true);assertEquals(false,apply.invoke(effect,mock(Character.class),b,false,new java.awt.Point(),false,1));verify(b,never()).applyHpMpChange(anyInt(),anyInt(),anyInt());}

 @Test void aNewParticipantWithNoDeathPropertyCanReviveNormally(){var b=exhausted();when(b.getEventInstance().getProperty("pinkDeaths:7")).thenReturn(null);when(b.getEventInstance().getIntProperty(anyString())).thenThrow(new NumberFormatException("unset property"));assertFalse(PinkBeanLives.exhausted(b));}
}
